declare const UserIdBrand: unique symbol;
export type UserId = string & { readonly [UserIdBrand]: never };

export function UserId(value: string): UserId {
  if (!/^usr_[a-z0-9]+$/.test(value)) throw new Error('invalid user id');
  return value as UserId;
}

function loadProfile(id: UserId) { return fetch(`/users/${id}`); }

loadProfile(UserId('usr_abc')); // ok
// loadProfile('usr_abc'); // compile error — string not assignable to UserId

const VALID_EMAIL = Symbol('validEmail');

export function createValidatedEmail(raw) {
  const email = String(raw).trim().toLowerCase();
  if (!email.includes('@')) throw new TypeError('invalid email');
  return Object.freeze({ email, [VALID_EMAIL]: true });
}

export function sendReceipt(validated) {
  if (validated[VALID_EMAIL] !== true) {
    throw new TypeError('expected validated email from factory');
  }
  return queueEmail(validated.email);
}

public readonly record struct UserId(string Value)
{
    public UserId(string value) : this(Validate(value)) { }
    private static string Validate(string value) =>
        value.StartsWith("usr_") ? value : throw new ArgumentException();
}

void Load(UserId id) => _repo.Get(id.Value);

